# Construct output grid based on Fill Gap hypothesis
# Fill interior of all rectangular structures with their border color

# Left rect (0): rows 2-7, cols 1-6
# Right rect (3): rows 1-7, cols 14-20  
# 6s U-shape (6): rows 5-7, cols 9-11 - fill the gap at (6,10)

rows = 11
cols = 27
output = [[9] * cols for _ in range(rows)]

# Fill right rectangle first (3s) - rows 1-7, cols 14-20
for r in range(1, 8):
    for c in range(14, 21):
        output[r][c] = 3

# Fill left rectangle (0s) - rows 2-7, cols 1-6
for r in range(2, 8):
    for c in range(1, 7):
        output[r][c] = 0

# Fill 6s U-shape - rows 5-7, cols 9-11 (fill gap)
for r in range(5, 8):
    for c in range(9, 12):
        output[r][c] = 6

# Print output grid
for row in output:
    print(' '.join(f'{x}' for x in row))

